import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        FCards fc = new FCards();
        fc.solve(1, sc, System.out);
        sc.close();
    }

    static class FCards {
        long mod = 998244353;

        long power(long base, long exp) {
            long result = 1;
            for (; exp > 0; exp >>= 1) {
                if ((exp & 1) == 1) {
                    result = (result * base) % mod;
                }
                base = (base * base) % mod;
            }
            return result;
        }

        public void solve(int testNumber, Scanner s, java.io.PrintStream out) {
            int n = s.nextInt(), m = s.nextInt(), k = s.nextInt();
            long[][] dp = new long[k + 1][Math.min(n, k) + 1];
            dp[0][0] = 1;
            for (int i = 1; i <= k; i++) {
                for (int j = 1; j <= Math.min(n, k); j++) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j] * j % mod) % mod;
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] * (n - j + 1) % mod) % mod;
                }
            }
            long invm = power(m, mod - 2);
            long res = 0;
            long prob = 1;
            for (int i = 0; i <= Math.min(n, k); i++) {
                res = (res + dp[k][i] * prob % mod) % mod;
                prob = prob * invm % mod;
            }
            out.println(res);
        }
    }
}
